<script setup lang="ts">
import {ref,onMounted,watch} from 'vue'
import {supabase} from '@/lib/supabase'
import {strategyAdminCommand} from '@/services/strategy-admin'
import {useBrandKit} from '@/composables/useBrandKit'
const props=defineProps<{kitId:string}>(),{loadBrandKit}=useBrandKit(),assets=ref<any>({}),pending=ref<any>({}),error=ref(''),notice=ref(''),busy=ref(false)
const emit=defineEmits(['saved']),stamp=ref('')
const labels:Record<string,string>={logo:'Logótipo principal',icon:'Ícone compacto',favicon:'Favicon'}
async function load(){const {data,error:e}=await supabase.from('brand_kits').select('logo_asset_id,icon_asset_id,favicon_asset_id,updated_at').eq('id',props.kitId).single();if(e)throw e;stamp.value=data.updated_at;assets.value={};for(const k of Object.keys(labels)){const id=(data as any)[k+'_asset_id'];if(id){const r=await supabase.from('brand_assets').select('id,mime_type,content_base64,width,height').eq('id',id).single();if(r.error)throw r.error;assets.value[k]={...r.data,url:`data:${r.data.mime_type};base64,${r.data.content_base64}`}}}}
async function choose(kind:string,event:Event){error.value='';notice.value='';const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;try{if(file.type!=='image/png'||file.size>2*1024*1024)throw new Error('Seleciona uma imagem PNG até 2 MB.');const url=await new Promise<string>((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result));r.onerror=reject;r.readAsDataURL(file)});const img=new Image();img.src=url;await img.decode();if(img.width>4096||img.height>4096)throw new Error('Máximo: 4096 × 4096 píxeis.');if(kind==='favicon'&&(img.width!==img.height||img.width>512))throw new Error('O favicon deve ser quadrado e ter no máximo 512 × 512 píxeis.');pending.value[kind]={url,width:img.width,height:img.height}}catch(e){error.value=(e as Error).message}}
async function save(kind:string){busy.value=true;error.value='';try{const before=stamp.value;await strategyAdminCommand('brand_asset_upload',props.kitId,{kind,content_base64:pending.value[kind].url.split(',')[1],expected_asset_id:assets.value[kind]?.id||null});delete pending.value[kind];await load();emit('saved',{before,after:stamp.value});await loadBrandKit();notice.value='Imagem guardada. A versão anterior mantém-se preservada.'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function refresh(){try{await load()}catch(e){error.value=(e as Error).message}}
onMounted(refresh);watch(()=>props.kitId,()=>{pending.value={};void refresh()})
</script>
<template><section class="border rounded p-3 mt-3"><h4 class="h6">Imagens da organização</h4><p class="small">PNG até 2 MB e 4096 × 4096 píxeis. O favicon deve ser quadrado, até 512 píxeis. Mantém as cores e a transparência do ficheiro original.</p><div v-if="error" class="alert alert-danger" role="alert">{{error}}</div><p v-if="notice" class="text-success" role="status">{{notice}}</p><div class="row g-3"><div v-for="(label,kind) in labels" :key="kind" class="col-md-4"><label :for="`asset-${kind}`" class="form-label">{{label}}</label><img v-if="pending[kind]||assets[kind]" :src="(pending[kind]||assets[kind]).url" :alt="label" class="d-block border rounded mb-2" style="max-width:100%;height:80px;object-fit:contain;background:#fff"><p class="small">{{pending[kind]?'Pré-visualização — por guardar':assets[kind]?'Imagem atual':'Sem imagem'}}</p><input :id="`asset-${kind}`" type="file" accept="image/png" class="form-control" :disabled="busy" @change="choose(kind,$event)"><button v-if="pending[kind]" type="button" class="btn btn-outline-primary mt-2" :disabled="busy" @click="save(kind)">Guardar imagem</button></div></div></section></template>
